def tokens(row):
    out=[]
    for v in row:
        if isinstance(v,tuple): out += [str(v[0]),'enter',str(v[1]),'enter',str(v[2]),'enter']
        else: out += [repr(v) if v!=int(v) else str(int(v)),'enter']
    return ' '.join(out)
